        self._enter_dy: int = 0
        self._enter_frames_left: int = 0
        self._init_action_bar()
        self._update_action_bar()
        nlcnihnakv = self.current_level.get_sprites_by_name("player")
        self.cflwkfoggh = nlcnihnakv[0] if nlcnihnakv else None
        self.all_sprites = self.current_level.get_sprites()
